package dev.pedro.learning.ecommerce.payment.messaging;import dev.pedro.learning.ecommerce.payment.application.PaymentSagaService;import dev.pedro.learning.ecommerce.payment.event.*;import io.smallrye.common.annotation.Blocking;import jakarta.enterprise.context.ApplicationScoped;import org.eclipse.microprofile.reactive.messaging.Incoming;@ApplicationScoped public class PaymentEventConsumer{private final EventJson json;private final PaymentSagaService saga;public PaymentEventConsumer(EventJson json,PaymentSagaService saga){this.json=json;this.saga=saga;}@Incoming("inventory-events-payment")@Blocking public void inventoryEvent(String value){RawEventEnvelope raw=json.parseRaw(value);if("StockReserved".equals(raw.eventType()))saga.onStockReserved(json.toTyped(raw,StockReservedPayload.class));}}